// An invented parcel desk: synthetic source for the resolve stage's citation tests.
export interface Scan { parcel: string; dock: string }

export function admit(scan: Scan, ledger: Map<string, string>): boolean {
  const row = ledger.get(scan.parcel);
  if (row === undefined) return false;
  return row === scan.dock;
}

export function label(scan: Scan): string {
  return `${scan.parcel}@${scan.dock}`;
}
